def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        row_coords = []
        for j, val in enumerate(row):
            if val == x:
                row_coords.append((i, j))
        # Sort by column in descending order within the same row
        row_coords.sort(key=lambda coord: coord[1], reverse=True)
        result.extend(row_coords)
    # Sort by row in ascending order (already mostly sorted by enumeration, but ensure correctness)
    result.sort(key=lambda coord: coord[0])
    return result

